const rows = $('Get row(s) in sheet').all();
const webhookData = $('Webhook').first().json;
const jiraData = webhookData.body ? webhookData.body.issue : webhookData.issue;
const epicName = $('Webhook').first().json.body.issue.fields.parent.fields.summary;
const attachments = jiraData.fields.attachment || [];

// ============================================================
// SHEET PROFILES
// Untuk tambah format baru: cukup tambah satu objek di sini
//
// signatureSource : "keys"   = cocokkan dari nama kolom n8n
//                  "values"  = cocokkan dari nilai baris-baris awal
// needsRemap      : true     = n8n baca header palsu (col_1, col_2, JMO, SMILE)
//                              → perlu remap ke nama kolom asli
//                  false     = n8n sudah baca header dengan benar
//                              → tidak perlu remap
// dataStartRow    : index baris n8n yang mulai dianggap sebagai data (0-based)
//                  0  = semua baris dari n8n adalah data
//                  2  = skip 2 baris pertama (baris label grup + baris header)
// noColumn        : nama kolom yang berisi nomor urut untuk filter baris valid
//                  null = tidak ada, semua baris non-kosong valid
// blocks          : blok kolom yang berulang dalam satu baris
//                  suffix '' = blok pertama, '_2' = blok kedua, dst.
// ============================================================
const SHEET_PROFILES = [
  {
    name            : "Antrian Online",
    signature       : ["kelas uji", "butir uji", "prosedur pengujian"],
    signatureSource : "keys",
    needsRemap      : false,
    dataStartRow    : 0,
    noColumn        : null,
    blocks          : [{ suffix: "", label: "default" }],
    map: {
      kelasUji : ["Kelas Uji", "KELAS UJI", "Kelas"],
      butirUji : ["Butir Uji", "BUTIR UJI", "Butir"],
      tanggal  : ["Tanggal Pengujian", "Tgl Pengujian", "Tanggal", "Jadwal"],
      masukan  : ["Data", "Masukan", "Input", "Data Masukan"],
      keluaran : ["Keluaran yg diharapkan", "Keluaran yang Diharapkan", "Hasil yang diharapkan", "Keluaran", "Output"],
      prosedur : ["Prosedur Pengujian", "Prosedur", "Langkah"],
      segmen   : []
    }
  },
  {
    name            : "JMO",
    signature       : ["jenis", "skenario", "test steps", "expected result"],
    signatureSource : "values",
    needsRemap      : true,
    dataStartRow    : 1,
    noColumn        : "NO",
    blocks          : [
      { suffix: "",   label: "JMO"   },
      { suffix: "_2", label: "SMILE" }
    ],
    map: {
      kelasUji : ["SKENARIO", "Skenario"],
      butirUji : ["SKENARIO", "Skenario"],
      tanggal  : ["Tanggal Pengujian", "Tgl Pengujian", "Tanggal", "Jadwal"],
      masukan  : [""],
      keluaran : ["EXPECTED RESULT", "Expected Result"],
      prosedur : ["TEST STEPS", "Test Steps"],
      preCondition : ["PRE-CONDITION", "Pre-Condition"],
      segmen   : ["SEGMEN", "Segmen"]
    }
  }
];

// ============================================================
// STEP 1: Deteksi profil
// ============================================================
function detectProfile(rows) {
  for (const profile of SHEET_PROFILES) {
    if (profile.signatureSource === "keys") {
      // Cocokkan dari nama kolom (key) n8n di baris pertama
      const keys = Object.keys(rows[0].json).map(k => k.toLowerCase().trim());
      const matchCount = profile.signature.filter(sig => keys.includes(sig)).length;
      if (matchCount >= Math.ceil(profile.signature.length * 0.75)) {
        return profile;
      }
    } else {
      // Cocokkan dari nilai baris-baris awal (max 5 baris)
      const maxScan = Math.min(5, rows.length);
      for (let i = 0; i < maxScan; i++) {
        const vals = Object.values(rows[i].json)
          .map(v => String(v || "").toLowerCase().trim())
          .filter(v => v !== "");
        const matchCount = profile.signature.filter(sig => vals.includes(sig)).length;
        if (matchCount >= Math.ceil(profile.signature.length * 0.75)) {
          return profile;
        }
      }
    }
  }
  // Fallback ke profil pertama
  return SHEET_PROFILES[0];
}

const profile = detectProfile(rows);

// ============================================================
// STEP 2: Bangun realHeaderMap (hanya kalau needsRemap = true)
// ============================================================
let realHeaderMap = {};

if (profile.needsRemap) {
  // Cari baris yang isinya cocok dengan signature profil ini
  const maxScan = Math.min(5, rows.length);
  for (let i = 0; i < maxScan; i++) {
    const vals = Object.values(rows[i].json)
      .map(v => String(v || "").toLowerCase().trim());
    const matchCount = profile.signature.filter(sig => vals.includes(sig)).length;
    if (matchCount >= Math.ceil(profile.signature.length * 0.75)) {
      const usedNames = {};
      for (const [key, val] of Object.entries(rows[i].json)) {
        if (!val || String(val).trim() === "") continue;
        let realKey = String(val).trim();
        if (usedNames[realKey]) {
          usedNames[realKey]++;
          realKey = `${realKey}_${usedNames[realKey]}`;
        } else {
          usedNames[realKey] = 1;
        }
        realHeaderMap[key] = realKey;
      }
      break;
    }
  }
}

// ============================================================
// STEP 3: Remap key col_N → nama kolom asli
// ============================================================
function remapRow(rowJson) {
  if (!profile.needsRemap || Object.keys(realHeaderMap).length === 0) return rowJson;
  const remapped = {};
  for (const [key, val] of Object.entries(rowJson)) {
    const realKey = realHeaderMap[key] || key;
    remapped[realKey] = val;
  }
  return remapped;
}

// ============================================================
// STEP 4: Filter baris valid + terapkan remap
// ============================================================
function isDataRow(rowJson, rowIndex) {
  // Buang baris sebelum dataStartRow
  if (rowIndex < profile.dataStartRow) return false;

  const vals = Object.values(rowJson).map(v => String(v || "").trim());
  if (vals.every(v => v === "")) return false;

  // Kalau profil punya noColumn, pastikan nilainya angka
  if (profile.noColumn) {
    const noKey = Object.keys(realHeaderMap).find(k => realHeaderMap[k] === profile.noColumn);
    const noVal = rowJson[noKey] ?? rowJson[profile.noColumn];
    if (noVal === undefined || noVal === null || noVal === "") return false;
    return !isNaN(parseFloat(noVal));
  }

  return true;
}

const validRows = rows
  .filter((row, i) => isDataRow(row.json, i))
  .map(row => ({ ...row, json: remapRow(row.json) }));

// ============================================================
// HELPER: getVal — cari nilai berdasarkan daftar alias
// ============================================================
function getVal(rowJson, aliases, fallback = "-") {
  for (const alias of aliases) {
    if (rowJson[alias] !== undefined && rowJson[alias] !== null && rowJson[alias] !== "") {
      return rowJson[alias];
    }
  }
  const rowKeysLower = Object.keys(rowJson).map(k => ({ original: k, lower: k.toLowerCase().trim() }));
  for (const alias of aliases) {
    const found = rowKeysLower.find(k => k.lower === alias.toLowerCase().trim());
    if (found && rowJson[found.original] !== undefined && rowJson[found.original] !== "") {
      return rowJson[found.original];
    }
  }
  return fallback;
}

// ============================================================
// HELPER: Ekstrak satu blok skenario (JMO atau SMILE)
// ============================================================
function extractSkenario(data, suffix) {
  const map = profile.map;

  // let butirAliases, prosedurAliases, keluaranAliases, preConditionAliases;
  let butirAliases, prosedurAliases, keluaranAliases;

  if (suffix === "") {
    // Blok pertama: pakai nama asli
    butirAliases        = map.butirUji;
    prosedurAliases     = map.prosedur;
    keluaranAliases     = map.keluaran;
    // preConditionAliases = map.preCondition || []; // Ambil dari map baru
  } else {
    // Blok kedua (SMILE): HANYA cari nama+suffix, tidak fallback ke tanpa suffix
    butirAliases        = map.butirUji.map(a => `${a}${suffix}`);
    prosedurAliases     = map.prosedur.map(a => `${a}${suffix}`);
    keluaranAliases     = map.keluaran.map(a => `${a}${suffix}`);
    // preConditionAliases = (map.preCondition || []).map(a => `${a}${suffix}`);
  }

  const rawButir   = getVal(data, butirAliases, "");
  const stepRaw    = getVal(data, prosedurAliases, "");
  const keluaran   = getVal(data, keluaranAliases, "");
  // const preCondRaw = getVal(data, preConditionAliases, "");

  // GABUNGKAN Pre-Condition dan Test Steps di sini
  let prosedurRaw = "";
  // if (preCondRaw) prosedurRaw += "[PRE-CONDITION]\n" + preCondRaw.trim() + "\n\n";
  // if (stepRaw) prosedurRaw += "[TEST STEPS]\n" + stepRaw.trim();
  if (stepRaw) prosedurRaw += stepRaw.trim();

  return { rawButir, prosedurRaw, keluaran };
}

// ============================================================
// HELPER: Normalisasi awalan "Pengujian" / "Pengujian pada"
// ============================================================
function normalizeButir(str) {
  if (!str || str === "-") return "-";
  if (/^pengujian\s+pada\s+/i.test(str)) return str;
  if (/^pengujian\s+/i.test(str)) return str;
  return `Pengujian pada ${str}`;
}

// ============================================================
// MAIN LOGIC
// ============================================================
let tabelIdentifikasiArr = [];
let tabelDeskripsiArr    = [];
let hasilPengujianArr    = [];
let currentKelasUji      = "";
let listMaterial         = [];
let targetTemplateId     = "";
let paCounter            = 0;

validRows.forEach((row) => {
  const data = row.json;
  const map  = profile.map;

  // Kolom shared
  let rawKelas = getVal(data, map.kelasUji, "");
  if (rawKelas.toString().trim() !== "") {
    currentKelasUji = rawKelas.toString().trim();
    if (!listMaterial.includes(currentKelasUji)) listMaterial.push(currentKelasUji);
  }
  const finalKelasUji = currentKelasUji;
  const tanggal       = getVal(data, map.tanggal, "-");
  const segmen        = getVal(data, map.segmen,  "");
  const testData      = getVal(data, map.masukan, "Data Peserta");
  const masukanParts  = [segmen, testData].filter(v => String(v).trim() !== "");
  const masukan       = masukanParts.length > 0 ? masukanParts.join("\n") : "-";

  // Ganti bagian entries dengan ini — identik dengan versi yang benar
  const jmo   = extractSkenario(data, '');
  const smile = extractSkenario(data, '_2');

  const hasJMO   = jmo.rawButir.trim()   !== "";
  const hasSMILE = smile.rawButir.trim() !== "";

  const entries = [];
  if (hasJMO)   entries.push(jmo);
  if (hasSMILE) entries.push(smile);
  if (!hasJMO && !hasSMILE) entries.push(jmo);

  entries.forEach(entry => {
    paCounter++;
    const idPA = `PA_${paCounter}`;

    const rawButir          = entry.rawButir || "-";
    const prosedurPengujian = entry.prosedurRaw.toString().replace(/\r\n/g, '\n').trim();
    const keluaran          = entry.keluaran || "-";
    const finalButir        = normalizeButir(rawButir.toString().trim());
    const cleanButir        = finalButir.replace(/^pengujian\s+(pada\s+)?/i, "").trim();
    const deskripsi         = cleanButir !== "-" ? `Menguji ${cleanButir}` : "-";

    const fileBuktiList = attachments.filter(att => {
      const filename    = att.filename.toUpperCase();
      const isMimeImage = att.mimeType && att.mimeType.startsWith('image/');
      const isNameMatch = filename.includes(idPA.toUpperCase() + ".") || filename.includes(idPA.toUpperCase() + "_");
      return isMimeImage && isNameMatch;
    });
    const urlJiraList = fileBuktiList.map(file => file.content);

    tabelIdentifikasiArr.push({
      "Kelas Uji"         : finalKelasUji,
      "Butir Uji"         : finalButir,
      "Identifikasi PA"   : idPA,
      "Tingkat Pengujian" : "Pengujian Sistem",
      "Jenis Pengujian"   : "Black box",
      "Jadwal"            : tanggal
    });

    tabelDeskripsiArr.push({
      "Identifikasi"             : idPA,
      "Deskripsi"                : deskripsi,
      "Prosedur Pengujian"       : prosedurPengujian,
      "Masukan"                  : masukan,
      "Keluaran yang Diharapkan" : keluaran,
      "Kriteria Evaluasi Hasil"  : "Sesuai",
      "Hasil yang Didapat"       : "Berhasil dilakukan",
      "Kesimpulan"               : "Diterima"
    });

    hasilPengujianArr.push({
      "deskripsi"    : deskripsi,
      "urlBuktiList" : urlJiraList
    });
  });
});

let materialPengujianTeks = "";
listMaterial.forEach((item, idx) => {
  materialPengujianTeks += `${idx + 1}. ${item}\n`;
});

if (epicName.includes("JMO")) {
  targetTemplateId = "1QKHIfIq7CrxUXQcyi8DM4HeBoIPXcn3UGcmtpPMQL2I";
} else if (epicName.includes("Antrian Online Lapak Asik")) {
  targetTemplateId = "1q6HK51D5j1_rDRKOFOKqRxS1nl9P0hMwKMR4sA6mU4s";
} else {
  targetTemplateId = "1q6HK51D5j1_rDRKOFOKqRxS1nl9P0hMwKMR4sA6mU4s";
}

return [{
  json: {
    judul_rphua        : $('Webhook').first().json.body.issue.fields.summary,
    judul_docs         : jiraData.fields.summary,
    template_id        : targetTemplateId,
    material_pengujian : materialPengujianTeks.trim(),
    tabel_identifikasi : tabelIdentifikasiArr,
    tabel_deskripsi    : tabelDeskripsiArr,
    hasil_pengujian    : hasilPengujianArr
  }
}];
